import requests

BASE_URL = "http://localhost:3000"
LOGIN_ENDPOINT = "/api/auth/login"
TIMEOUT = 30

def test_authentication_api_login_with_valid_credentials():
    url = BASE_URL + LOGIN_ENDPOINT
    payload = {
        "username": "jose",
        "password": "password123"
    }
    headers = {
        "Content-Type": "application/json"
    }

    try:
        resp = requests.post(url, json=payload, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request failed: {e}"

    assert resp.status_code == 200, f"Expected status code 200, got {resp.status_code}"

    try:
        data = resp.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    assert "token" in data and isinstance(data["token"], str) and data["token"], "Missing or invalid token field"
    assert "user" in data and isinstance(data["user"], dict), "Missing or invalid user field"

    user = data["user"]
    required_user_fields = ["id", "username", "fullName", "role"]
    for field in required_user_fields:
        assert field in user, f"User object missing '{field}'"
    assert isinstance(user["id"], int), "User id should be an integer"
    assert isinstance(user["username"], str) and user["username"], "Invalid username"
    assert isinstance(user["fullName"], str) and user["fullName"], "Invalid fullName"
    assert isinstance(user["role"], str) and user["role"], "Invalid role"

test_authentication_api_login_with_valid_credentials()

import requests

def test_authentication_api_login_with_invalid_credentials_returns_401():
    url = "http://localhost:3000/api/auth/login"
    headers = {
        "Content-Type": "application/json"
    }
    invalid_payloads = [
        {"username": "nonexistentuser", "password": "somepassword"},
        {"username": "jose", "password": "wrongpassword"},
        {"username": "", "password": "password123"},
        {"username": "jose", "password": ""}
    ]
    for payload in invalid_payloads:
        try:
            resp = requests.post(url, json=payload, headers=headers, timeout=30)
            if not payload["username"] or not payload["password"]:
                # Missing fields - expect 400
                assert resp.status_code == 400, f"Expected 400, got {resp.status_code} for payload {payload}"
                json_resp = resp.json()
                assert isinstance(json_resp, list) or isinstance(json_resp, dict), f"Expected validation error format for payload {payload}"
            else:
                # Invalid credentials - expect 401
                assert resp.status_code == 401, f"Expected 401, got {resp.status_code} for payload {payload}"
                json_resp = resp.json()
                assert "invalid" in resp.text.lower() or "error" in resp.text.lower() or "message" in json_resp, \
                    f"Expected error message in response body for payload {payload}"
        except requests.RequestException as e:
            assert False, f"Request failed: {e}"

test_authentication_api_login_with_invalid_credentials_returns_401()

import requests

BASE_URL = "http://localhost:3000"

def test_dashboard_stats_returns_aggregated_counts():
    # Step 1: Authenticate as admin to get Bearer token
    login_url = f"{BASE_URL}/api/auth/login"
    login_payload = {
        "username": "jose",
        "password": "password123"
    }
    try:
        login_resp = requests.post(login_url, json=login_payload, timeout=30)
        assert login_resp.status_code == 200, f"Login failed with status {login_resp.status_code}"
        login_data = login_resp.json()
        token = login_data.get("token")
        assert token, "Token not found in login response"
    except requests.RequestException as e:
        assert False, f"Login request exception: {e}"

    headers = {
        "Authorization": f"Bearer {token}"
    }

    # Step 2: Call GET /api/dashboard/stats with Bearer token
    stats_url = f"{BASE_URL}/api/dashboard/stats"
    try:
        stats_resp = requests.get(stats_url, headers=headers, timeout=30)
        assert stats_resp.status_code == 200, f"Unexpected status code: {stats_resp.status_code}"
        data = stats_resp.json()
    except requests.RequestException as e:
        assert False, f"Dashboard stats request exception: {e}"
    except ValueError as e:
        assert False, f"Invalid JSON returned: {e}"

    # Step 3: Validate response keys and values
    expected_keys = {"totalItems", "transactionsMTD", "activeVendors", "teamMembers"}
    assert set(data.keys()) == expected_keys, f"Response keys mismatch. Expected {expected_keys}, got {set(data.keys())}"

    for key in expected_keys:
        value = data[key]
        assert isinstance(value, int), f"Value of {key} is not int: {value}"
        assert value >= 0, f"Value of {key} is negative: {value}"

test_dashboard_stats_returns_aggregated_counts()
